/** Sensitivity analysis: dictionary arithmetic, ranges, reoptimization, value functions. */
import {raw,box,math} from './duality-common.js';
const p=s=>`<p>${s}</p>`;
const table=(heads,rows)=>`<div class="dy-table-wrap" tabindex="0" role="region" aria-label="Scrollable comparison table"><table class="dy-table"><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((v,i)=>i?`<td>${v}</td>`:`<th scope="row">${v}</th>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const pair=(body,figure)=>`<div class="dy-pair"><div class="dy-stack">${body}</div>${figure}</div>`;
const slide=(key,title,html,referencePages=[],options={})=>({id:`l22-${key}`,key,title,html,referencePages,className:'dy-slide se-slide',...options});
const cp=(prompt,choices,correctIndex,explanation)=>({prompt,choices,correctIndex,explanation,autoOpen:true});
const link=(key,label)=>`<a data-s22-link="${key}" href="#slide=1">${label}</a>`;
const full=()=>math(raw`\begin{aligned}\max\quad &z=2x+3y\\\text{s.t.}\quad &x+y\le9&&\text{(hours)},\\&2x+y\le16&&\text{(flour)},\\&x+2y\le14&&\text{(sugar)},\\&x,y\ge0.\end{aligned}`);
const compact=()=>`<div class="dy-problem">${p(raw`<strong>Bakery:</strong> maximize \(z=2x+3y\), with \(x+y\le9\), \(2x+y\le16\), \(x+2y\le14\), \(x,y\ge0\).`)}</div>`;
const dict=()=>math(raw`\begin{aligned}x&=4-2s_1+s_3,\\y&=5+s_1-s_3,\\s_2&=3+3s_1-s_3,\\z&=23-s_1-s_3.\end{aligned}`);
export const bakery={A:[[1,1],[2,1],[1,2]],b:[9,16,14],c:[2,3],basis:['x','y','s2'],inverse:[[2,0,-1],[-1,0,1],[-3,1,1]],x:[4,5],slacks:[0,3,0],dual:[1,0,1],value:23};
export function rhsState(row,delta){
 const b=[9,16,14];b[row]+=delta;const dd=[0,0,0];dd[row]=delta;
 const basis=[4+2*dd[0]-dd[2],5-dd[0]+dd[2],3-3*dd[0]+dd[1]+dd[2]];
 const lines=[...bakery.A.map((a,i)=>[...a,b[i]]),[1,0,0],[0,1,0]];
 const vertices=[];
 for(let i=0;i<lines.length;i++)for(let j=i+1;j<lines.length;j++){
 const [a,c,e]=lines[i],[d,f,g]=lines[j],det=a*f-c*d;if(Math.abs(det)<1e-12)continue;
 const x=(e*f-c*g)/det,y=(a*g-e*d)/det;
 if(x>=-1e-9&&y>=-1e-9&&bakery.A.every((q,k)=>q[0]*x+q[1]*y<=b[k]+1e-9)&&!vertices.some(v=>Math.hypot(v[0]-x,v[1]-y)<1e-8))vertices.push([x,y]);
 }
 if(vertices.length){const center=vertices.reduce((s,v)=>[s[0]+v[0]/vertices.length,s[1]+v[1]/vertices.length],[0,0]);vertices.sort((a,b)=>Math.atan2(a[1]-center[1],a[0]-center[0])-Math.atan2(b[1]-center[1],b[0]-center[0]));}
 const best=vertices.reduce((a,v)=>!a||2*v[0]+3*v[1]>2*a[0]+3*a[1]+1e-9?v:a,null);
 return {b,basis,vertices,best,predicted:23+dd[0]+dd[2],value:best?2*best[0]+3*best[1]:null,feasible:basis.every(v=>v>=-1e-9)};
}
const fmt=x=>Number.isInteger(x)?`${x}`:x.toFixed(2).replace(/0+$/,'').replace(/\.$/,'');
const resourceNames=['Hours','Flour','Sugar'];
const resourceColors=['#326b8c','#a04b13','#177441'];
const resourcePatterns=['','10 5','10 4 2 4'];
let graphSerial=0;
export function bakeryGraphic(row=0,delta=0,{answers=true}={}){
 const q=rhsState(row,delta),X=x=>80+29*x,Y=y=>185-12.5*y,id=`se-clip-${++graphSerial}`;
 const segments=q.b.map((v,i)=>{const [a,b]=bakery.A[i];return [[-2,(v+2*a)/b],[12,(v-12*a)/b]];});
 const labels=[1.2,5.5,9].map((x,i)=>[x,(q.b[i]-bakery.A[i][0]*x)/bakery.A[i][1]]);
 return `<svg viewBox="0 0 500 240" role="img" aria-label="Bakery feasible region. Hours ${q.b[0]}, flour ${q.b[1]}, sugar ${q.b[2]}.${answers?` Optimal quantities ${q.best?q.best.map(fmt).join(', '):'none'}. Original basis ${q.feasible?'feasible':'infeasible'}.`:' Practice: solution markers are hidden.'}">
 <defs><clipPath id="${id}"><rect x="20" y="25" width="408" height="200"/></clipPath></defs>
 <g clip-path="url(#${id})"><polygon points="${q.vertices.map(v=>`${X(v[0])},${Y(v[1])}`).join(' ')}" fill="#d8eaf3"/>
 ${segments.map((a,i)=>`<line data-se-resource="${i}" x1="${X(a[0][0])}" y1="${Y(a[0][1])}" x2="${X(a[1][0])}" y2="${Y(a[1][1])}" stroke="${resourceColors[i]}" stroke-width="${i===row?4:2.5}" stroke-dasharray="${resourcePatterns[i]}"/>`).join('')}
 ${answers&&q.best?`<line data-se-profit-line x1="${X(-2)}" y1="${Y((q.value+4)/3)}" x2="${X(12)}" y2="${Y((q.value-24)/3)}" stroke="#861f41" stroke-width="2" stroke-dasharray="2 5"/>`:''}</g>
 <path d="M80 25V225M20 185H440" stroke="#5d707a" stroke-width="1.5" fill="none"/>
 ${[-2,0,4,8,12].map(x=>`<text x="${X(x)}" y="207" text-anchor="middle">${x}</text>`).join('')}
 ${[4,8,12].map(y=>`<text x="70" y="${Y(y)+7}" text-anchor="end">${y}</text>`).join('')}
 <text x="350" y="235">Bread x</text><text x="87" y="22">Cakes y</text>
 ${labels.map((v,i)=>`<text data-se-line-label="${i}" x="${X(v[0])+8}" y="${Y(v[1])-10}" style="fill:${resourceColors[i]};paint-order:stroke;stroke:#f7fafc;stroke-width:5px;font-weight:700">${resourceNames[i]}</text>`).join('')}
 ${answers?`<circle data-se-basis-point cx="${X(q.basis[0])}" cy="${Y(q.basis[1])}" r="10" stroke="${q.feasible?'#861f41':'#a04b13'}" fill="white" stroke-width="3"/>`:''}
 ${answers&&q.best?`<circle data-se-optimum cx="${X(q.best[0])}" cy="${Y(q.best[1])}" r="4.5" fill="#861f41"/>`:''}
 </svg>`;
}
const plotLegend=()=>`<figcaption>○ Original basis · ● Optimum<br>Shading: feasible plans · Dotted: profit line</figcaption>`;
const graphFigure=(row=0,delta=0)=>`<figure class="dy-figure se-plot">${bakeryGraphic(row,delta)}${plotLegend()}</figure>`;
const dictionaryBlock=(label,tex)=>`<section class="se-dictionary"><h3>${label}</h3>${math(tex)}</section>`;
const originalTex=raw`\begin{aligned}x&=4-2s_1+s_3,\\y&=5+s_1-s_3,\\s_2&=3+3s_1-s_3,\\z&=23-s_1-s_3.\end{aligned}`;
const originalBlock=()=>dictionaryBlock('Original dictionary',originalTex);
const changedConstant=t=>t.includes("\\delta")?raw`{\color{#861f41}${t}}`:t;
const rhsTex=row=>{
 const constants=[['4+2\\delta','5-\\delta','3-3\\delta','23+\\delta'],['4','5','3+\\delta','23'],['4-\\delta','5+\\delta','3+\\delta','23+\\delta']][row];
 return raw`\begin{aligned}x&=${changedConstant(constants[0])}-2s_1+s_3,\\y&=${changedConstant(constants[1])}+s_1-s_3,\\s_2&=${changedConstant(constants[2])}+3s_1-s_3,\\z&=${changedConstant(constants[3])}-s_1-s_3.\end{aligned}`;
};
const resourceModel=(row)=>p(raw`Maximize \(2x+3y\); \(x+y\le${row===0?'9+\\delta':'9'},\ 2x+y\le${row===1?'16+\\delta':'16'},\ x+2y\le${row===2?'14+\\delta':'14'},\ x,y\ge0\).`);
const rhsReading=(row,d,answers=true)=>{
 const state=rhsState(row,d),rhs=`${resourceNames[row]} limit: ${fmt(state.b[row])}.`;
 return rhs+(answers?` Original basis: ${fmt(state.basis[0])} bread, ${fmt(state.basis[1])} cakes, ${fmt(state.basis[2])} unused flour (${state.feasible?'feasible':'infeasible'}). Profit ${fmt(state.predicted)}; optimum ${fmt(state.value)}.`:' Find the updated dictionary and its allowable interval.');
};
const rhsWidget=(row,{answers=true,printDelta=0,initialDelta=0}={})=>`<div class="se-rhs-panel" data-se-fixed-row="${row}" data-se-answers="${answers}" data-se-initial-delta="${initialDelta}"><div class="se-screen-rhs"><figure class="dy-figure se-plot"><div data-se-chart>${bakeryGraphic(row,initialDelta,{answers})}</div>${answers?plotLegend():'<figcaption>Shading: feasible plans. Find the dictionary and range.</figcaption>'}</figure><div class="dy-controls"><label>${resourceNames[row]} ${raw`\(\delta=\)`}<output data-se-delta-value>${initialDelta}</output><input data-se-delta aria-label="${resourceNames[row]} change delta" type="range" min="${row===0?-3:-4}" max="${row===0?2:row===1?4:5}" step="0.5" value="${initialDelta}"></label><button type="button" data-se-reset>Reset</button></div><p class="se-rhs-status" data-se-status role="status" aria-live="polite">${rhsReading(row,initialDelta,answers)}</p></div><div class="se-print-rhs"><figure class="dy-figure se-plot">${bakeryGraphic(row,printDelta,{answers})}${answers?plotLegend():''}</figure><p class="se-rhs-status"><strong>Shown: ${raw`\(\delta=${printDelta}\)`}.</strong> ${rhsReading(row,printDelta,answers)}</p></div></div>`;
const savedRHS=new Map();
function mountRHS({$,slide}){
 const root=$('.se-rhs-panel'),row=+root.dataset.seFixedRow,answers=root.dataset.seAnswers==='true',delta=$('[data-se-delta]'),chart=$('[data-se-chart]'),status=$('[data-se-status]'),reset=$('[data-se-reset]');
 const key=slide.id,initialDelta=+root.dataset.seInitialDelta;delta.value=String(savedRHS.get(key)??initialDelta);
 const update=()=>{const d=+delta.value,state=rhsState(row,d);savedRHS.set(key,d);root.dataset.state=JSON.stringify({row,delta:d,...state});chart.innerHTML=bakeryGraphic(row,d,{answers});status.textContent=rhsReading(row,d,answers);root.querySelector('[data-se-delta-value]').textContent=fmt(d);delta.setAttribute('aria-valuetext',`${resourceNames[row]} change ${d}; total ${state.b[row]}`);};
 const restart=()=>{delta.value=String(initialDelta);update();};delta.addEventListener('input',update);reset.addEventListener('click',restart);update();
 return()=>{delta.removeEventListener('input',update);reset.removeEventListener('click',restart);};
}
const rhsOptions={className:'dy-slide se-slide se-rhs-page',onMount:mountRHS};
const compareDictionaries=(first,second,label='Updated dictionary',firstLabel='Original dictionary')=>table(['Variable',firstLabel,label],first.map((v,i)=>[raw`\(${['x','y','s_2','z'][i]}\)`,raw`\(${v}\)`,raw`\(${second[i]}\)`]));
const originalRows=[raw`4-2s_1+s_3`,raw`5+s_1-s_3`,raw`3+3s_1-s_3`,raw`23-s_1-s_3`];
const compactOriginal=()=>dictionaryBlock('Original optimal dictionary',raw`\begin{aligned}x&=4-2s_1+s_3,&\quad y&=5+s_1-s_3,\\s_2&=3+3s_1-s_3,& z&=23-s_1-s_3.\end{aligned}`);
const pastryModel=(changed=false)=>`<div class="dy-problem">${p(raw`<strong>With pastry \(t\):</strong> maximize \(z=2x+3y+4t\).`)+p(raw`\(x+y+${changed?'(1+\\delta)':''}t\le9\) (hours), \(2x+y+2t\le16\) (flour), \(x+2y+t\le14\) (sugar); \(x,y,t\ge0\).`)}</div>`;
const algebraOptions={className:'dy-slide se-slide se-algebra-page'};
const originalReset=()=>p(raw`<strong>Start again from the original bakery:</strong> hours 9, flour 16, sugar 14; maximize \(2x+3y\).`);
function valueGraphic(kind){
 const rhs=kind==='rhs',points=rhs?[[0,0],[7,-21],[10,-24],[12,-24]]:[[0,-21],[1.5,-21],[3,-27],[6,-48],[7,-56]],xmin=0,xmax=rhs?12:7,ymin=rhs?-27:-60,ymax=rhs?2:-15;
 const X=x=>62+x/(xmax-xmin)*380,Y=y=>300-(y-ymin)/(ymax-ymin)*250;
 return `<figure class="dy-figure"><svg viewBox="0 0 490 380" role="img" aria-label="${rhs?'Minimum negative profit as hours T vary: slope minus 3 to T7, minus 1 to T10, then zero; convex piecewise linear.':'Minimum negative profit as bread profit q varies: slopes 0, minus 4, minus 7, minus 8 with breakpoints 1.5, 3, 6; concave piecewise linear.'}"><path d="M62 35V315H455" fill="none" stroke="#5d707a" stroke-width="2"/>
 ${rhs?`<line x1="${X(0)}" y1="${Y(-14)}" x2="${X(12)}" y2="${Y(-26)}" stroke="#a04b13" stroke-width="2" stroke-dasharray="5 5"/>`:''}
 <polyline points="${points.map(v=>`${X(v[0])},${Y(v[1])}`).join(' ')}" fill="none" stroke="#861f41" stroke-width="4"/>
 ${points.map(v=>`<circle cx="${X(v[0])}" cy="${Y(v[1])}" r="5" fill="#861f41"/><text x="${X(v[0])}" y="339" text-anchor="middle">${v[0]}</text>`).join('')}
 ${[...new Set(points.map(v=>v[1]))].map(y=>`<text x="54" y="${Y(y)+5}" text-anchor="end">${y}</text>`).join('')}
 <text x="73" y="24">Minimum negative profit</text><text x="300" y="369">${rhs?'Hours T':'Bread profit q'}</text></svg><figcaption>${rhs?'The dashed line −T−14 is the global lower bound supplied by the dual solution at T=9.':'Each line is the cost of a fixed feasible production plan. The minimum selects the best plan.'}</figcaption></figure>`;
}
